Author: Frederik Deweerdt <fdeweerdt@fastly.com>
Date:   Thu Mar 21 13:19:11 2019 -0700

    Fix heap-buffer-overflow READ

    It's possible that byte_index goes past last_byte1 after we read the
    OID. Add a check for that.

    Credit to OSS-Fuzz

diff --git a/lib/minicrypto-pem.c b/lib/minicrypto-pem.c
index 08df52d..f40d225 100644
--- a/lib/minicrypto-pem.c
+++ b/lib/minicrypto-pem.c
@@ -106,6 +106,10 @@ size_t ptls_minicrypto_asn1_decode_private_key(ptls_asn1_pkcs8_private_key_t *pk
         }
     }

+    if (last_byte1 < byte_index) {
+        byte_index = ptls_asn1_error_message("Length larger than message", bytes_max, byte_index, 0, log_ctx);
+        *decode_error = PTLS_ERROR_BER_EXCESSIVE_LENGTH;
+    }
     if (*decode_error == 0) {
         /* get parameters, ANY */
         if (log_ctx != NULL) {
